<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Safe Practice Editor</title><style>body{margin:0;background:#0f172a;color:#e2e8f0;font:15px Inter,system-ui}.bar{display:flex;gap:10px;align-items:center;padding:14px 20px;background:#111c34}.bar a{color:#93c5fd}.btn,select{padding:10px 14px;border:0;border-radius:7px}.btn{background:#2563eb;color:#fff;font-weight:700;cursor:pointer}.grid{display:grid;grid-template-columns:1fr 1fr;height:calc(100vh - 68px)}textarea{width:100%;height:100%;padding:18px;resize:none;box-sizing:border-box;background:#111827;color:#d1fae5;border:0;font:14px/1.6 Consolas,monospace}iframe{width:100%;height:100%;border:0;background:#fff}@media(max-width:750px){.grid{grid-template-columns:1fr;height:auto}textarea,iframe{height:45vh}}</style></head><body><div class="bar"><a href="/learn">← Learning</a><select id="language"><option value="html">HTML/CSS/JavaScript</option><option value="javascript">JavaScript console</option></select><button class="btn" id="run">▶ Run code</button><span>Runs only inside a sandboxed browser frame.</span></div><main class="grid"><textarea id="code" spellcheck="false"><!doctype html>
<html><style>body{font-family:system-ui;padding:30px;color:#10213e}button{padding:10px}</style><body><h1>Hello EngineerLaunch</h1><button onclick="document.querySelector('h1').textContent='It works!'">Test JavaScript</button></body></html></textarea><iframe id="output" sandbox="allow-scripts"></iframe></main><script>const code=document.querySelector('#code'),output=document.querySelector('#output'),language=document.querySelector('#language');function run(){const value=language.value==='javascript'?`<!doctype html><pre id="out"></pre><script>const write=(...x)=>document.querySelector('#out').textContent+=x.join(' ')+'\\n';console.log=write;try{${code.value}}catch(e){write(e.name+': '+e.message)}<\/script>`:code.value;output.srcdoc=value}document.querySelector('#run').onclick=run;language.onchange=()=>{code.value=language.value==='javascript'?"console.log('Hello from JavaScript');\nconsole.log([1,2,3].map(x => x * 2));":'<!doctype html>\n<h1>Build something</h1>';run()};run();</script></body></html>
